1	package tui
2	
3	import (
4		"strings"
5	
6		"github.com/charmbracelet/bubbles/viewport"
7		"github.com/charmbracelet/lipgloss"
8	
9		"github.com/immuta/operations/apps/birdseye/internal/diff"
10	)
11	
12	// Browser is the multi-pane diff viewer: file tree on the left,
13	// rendered unified diff on the right, footer at the bottom.
14	type Browser struct {
15		result   diff.Result
16		theme    Theme
17		selected int
18		width    int
19		height   int
20		viewport viewport.Model
21	}
22	
23	// NewBrowser builds a Browser from a pre-computed Result. SetSize must
24	// be called once before the first View() so the viewport sizes itself.
25	func NewBrowser(r diff.Result) *Browser {
26		vp := viewport.New(0, 0)
27		return &Browser{
28			result:   r,
29			theme:    DefaultTheme(),
30			viewport: vp,
31		}
32	}
33	
34	// SetSize informs the browser of the terminal dimensions.
35	func (b *Browser) SetSize(w, h int) {
36		b.width, b.height = w, h
37		fileTreeW := 32
38		if w < 80 {
39			fileTreeW = 24
40		}
41		contentW := w - fileTreeW - 4
42		contentH := h - 2
43		if contentW < 10 {
44			contentW = 10
45		}
46		if contentH < 5 {
47			contentH = 5
48		}
49		b.viewport.Width = contentW
50		b.viewport.Height = contentH
51		b.refreshViewport()
52	}
53	
54	// SelectedIndex returns the currently focused file diff index.
55	func (b *Browser) SelectedIndex() int { return b.selected }
56	
57	// SelectedFile returns the FileDiff at the current selection. Falls
58	// back to a zero value when the result has no files.
59	func (b *Browser) SelectedFile() diff.FileDiff {
60		if len(b.result.Files) == 0 {
61			return diff.FileDiff{}
62		}
63		return b.result.Files[b.selected]
64	}
65	
66	// Move adjusts the selection by delta, clamping to the valid range, and
67	// refreshes the viewport content.
68	func (b *Browser) Move(delta int) {
69		if len(b.result.Files) == 0 {
70			return
71		}
72		b.selected += delta
73		if b.selected < 0 {
74			b.selected = 0
75		}
76		if b.selected >= len(b.result.Files) {
77			b.selected = len(b.result.Files) - 1
78		}
79		b.refreshViewport()
80	}
81	
82	func (b *Browser) refreshViewport() {
83		if len(b.result.Files) == 0 {
84			b.viewport.SetContent("no differences")
85			return
86		}
87		b.viewport.SetContent(b.colorizeUnified(b.SelectedFile().Unified))
88		b.viewport.GotoTop()
89	}
90	
91	func (b *Browser) colorizeUnified(unified string) string {
92		var sb strings.Builder
93		for _, line := range strings.Split(unified, "\n") {
94			switch {
95			case strings.HasPrefix(line, "@@"):
96				sb.WriteString(b.theme.HunkHeader.Render(line))
97			case strings.HasPrefix(line, "+") && !strings.HasPrefix(line, "+++"):
98				sb.WriteString(b.theme.AddedLine.Render(line))
99			case strings.HasPrefix(line, "-") && !strings.HasPrefix(line, "---"):
100				sb.WriteString(b.theme.RemovedLine.Render(line))
101			default:
102				sb.WriteString(line)
103			}
104			sb.WriteByte('\n')
105		}
106		return sb.String()
107	}
108	
109	// View renders the full multi-pane layout.
110	func (b *Browser) View() string {
111		tree := b.renderTree()
112		right := b.theme.Viewport.Render(b.viewport.View())
113		body := lipgloss.JoinHorizontal(lipgloss.Top, tree, right)
114		footer := b.theme.Footer.Render("j/k or ↑/↓ move · q quit · esc back")
115		return lipgloss.JoinVertical(lipgloss.Left, body, footer)
116	}
117	
118	func (b *Browser) renderTree() string {
119		var sb strings.Builder
120		for i, fd := range b.result.Files {
121			marker := " "
122			switch fd.Status {
123			case diff.StatusAdded:
124				marker = b.theme.StatusAdd.Render("+")
125			case diff.StatusRemoved:
126				marker = b.theme.StatusDel.Render("-")
127			case diff.StatusModified:
128				marker = b.theme.StatusMod.Render("~")
129			}
130			line := marker + " " + fd.Path
131			if i == b.selected {
132				line = b.theme.FileSelected.Render(line)
133			} else {
134				line = b.theme.FileTreeItem.Render(line)
135			}
136			sb.WriteString(line)
137			sb.WriteByte('\n')
138		}
139		if len(b.result.Files) == 0 {
140			sb.WriteString("(no files)")
141		}
142		return b.theme.FileTree.Render(sb.String())
143	}
