9	func sampleResult() diff.Result {
10		return diff.Result{Files: []diff.FileDiff{
11			{Path: "a.tf", Status: diff.StatusModified, Unified: "@@\n-x\n+y\n", Adds: 1, Dels: 1},
12			{Path: "b.tf", Status: diff.StatusAdded, Unified: "+++ b.tf\n+new\n", Adds: 1},
13		}}
14	}
