16	func TestNewBrowserDefaults(t *testing.T) {
17		b := NewBrowser(sampleResult())
18		if b.SelectedIndex() != 0 {
19			t.Errorf("default selected index = %d, want 0", b.SelectedIndex())
20		}
21		if b.SelectedFile().Path != "a.tf" {
22			t.Errorf("first selected = %s", b.SelectedFile().Path)
23		}
24	}
