26	func TestBrowserViewContainsBothFiles(t *testing.T) {
27		b := NewBrowser(sampleResult())
28		b.SetSize(120, 30)
29		view := b.View()
30		for _, want := range []string{"a.tf", "b.tf"} {
31			if !contains(view, want) {
32				t.Errorf("view missing %q\n%s", want, view)
33			}
34		}
35	}
